sub = np.arange(0,2880,20)  # 144 prompts
R0 = run(X[sub])
base_pred = R0.argmax(1)
def score(Lg):
    return (Lg.argmax(1)==base_pred).mean(), np.abs(Lg-R0).mean()
res={}
for L in range(0,13):
    for p in [0,1,2,3,4]:
        A = acts(X[sub], [f"resid{L}@{p}"])[f"resid{L}@{p}"]
        m = A.mean(0, keepdims=True)
        Lg = run(X[sub], hook={f"resid{L}@{p}": m})
        res[(L,p)] = score(Lg)
for L in range(13):
    print(L, " ".join(f"p{p}:{res[(L,p)][0]:.2f}/{res[(L,p)][1]:.2f}" for p in range(5)))

sub = np.arange(0,2880,20)
R0 = run(X[sub]); T0 = R0[:,1]-R0[:,0]; U0=R0[:,2]-R0[:,0]
def sens(hook):
    Rg = run(X[sub], hook=hook)
    return (Rg.argmax(1)==R0.argmax(1)).mean(), (Rg[:,1]-Rg[:,0]-T0).mean(), (Rg[:,2]-Rg[:,0]-U0).mean()
for L in range(12):
    for kind in ["attn","mlp"]:
        for p in [1,2,4]:
            A = acts(X[sub],[f"{kind}{L}@{p}"])[f"{kind}{L}@{p}"].mean(0,keepdims=True)
            s = sens({f"{kind}{L}@{p}": A})
            print(f"{kind}{L}@{p}  keep {s[0]:.2f}  dT {s[1]:+.2f} dU {s[2]:+.2f}")

